exec("import sys,subprocess; subprocess.check_call([sys.executable,'-m','pip','-q','install','yfinance','requests']); import requests,pandas as pd,numpy as np,yfinance as yf; from concurrent.futures import ThreadPoolExecutor; base='https://nsearchives.nseindia.com/content/indices/'; headers={'User-Agent':'Mozilla/5.0'}; syms=[]; \nfor f in ['ind_niftymidcap150list.csv','ind_niftysmallcap250list.csv']:\n try: syms+=pd.read_csv(requests.get(base+f,headers=headers,timeout=15).content).__getitem__('Symbol').dropna().astype(str).tolist()\n except Exception as e: print('NSE list fetch failed:',f,str(e)[:80])\nsyms=sorted(set(x.strip()+'.NS' for x in syms if x.strip() and 'DUMMY' not in x.upper())); print('Universe:',len(syms));\nif not syms: raise RuntimeError('Could not fetch NSE constituents; retry later.')\nz=yf.download(syms,period='1y',interval='1d',group_by='ticker',auto_adjust=True,threads=True,progress=False); radar=[];\nfor t in syms:\n try:\n  d=z[t].dropna(how='all') if isinstance(z.columns,pd.MultiIndex) and t in z.columns.get_level_values(0) else pd.DataFrame();\n  if len(d)<70: continue\n  c=d.Close.astype(float); h=d.High.astype(float); l=d.Low.astype(float); v=d.Volume.astype(float); prev=float(c.iloc[-2]); cmp=float(c.iloc[-1]); ma20=float(c.iloc[-21:-1].mean()); ma50=float(c.iloc[-51:-1].mean()); hi20=float(h.iloc[-21:-1].max()); lo60=float(l.iloc[-61:-1].min()); vol20=float(v.iloc[-21:-1].mean()); rng=((h-l)/c).tail(5); range5=float(rng.mean()); pullback=1-cmp/float(h.iloc[-21:-1].max()); ret60=prev/float(c.iloc[-61])-1; higher_lows=float(l.iloc[-1])>=float(l.iloc[-5:-1].min()); dry=float(v.iloc[-1])<=vol20*1.15; near_high=cmp>=hi20*.94; trend=(prev>ma20 and ma20>ma50 and ret60>=.10); tight=range5<=.045 and pullback<=.12 and higher_lows;\n  if cmp>=30 and vol20>=100000 and trend and tight and near_high: radar.append({'Symbol':t.replace('.NS',''),'CMP':round(cmp,2),'60D_Trend_%':round(ret60*100,1),'Pullback_from_20D_High_%':round(pullback*100,1),'5D_Avg_Range_%':round(range5*100,2),'Volume_Dry':dry,'Breakout_Level':round(hi20*1.001,2),'Stage':'NEAR BREAKOUT' if cmp<hi20 else 'BREAKOUT AREA'})\n except Exception: pass\nr=pd.DataFrame(radar); r.to_csv('early_entry_radar.csv',index=False); alerts=[];\nfor _,a in r.sort_values(['Volume_Dry','60D_Trend_%'],ascending=[False,False]).head(35).iterrows():\n try:\n  t=a.Symbol+'.NS'; q=yf.download(t,period='5d',interval='5m',auto_adjust=True,progress=False); q.columns=q.columns.get_level_values(0) if isinstance(q.columns,pd.MultiIndex) else q.columns;\n  if len(q)<10: continue\n  px=float(q.Close.iloc[-1]); vv=float(q.Volume.iloc[-1]); av=float(q.Volume.tail(30).iloc[:-1].mean()); level=float(a.Breakout_Level); crossed=px>level and float(q.Close.iloc[-2])<=level; surge=av>0 and vv>=1.5*av;\n  if crossed and surge: alerts.append({'Symbol':a.Symbol,'Latest_5m_Price':round(px,2),'Breakout_Level':level,'Last_5m_Volume_vs_30bar_Avg':round(vv/av,2),'Signal':'5-MIN BREAKOUT + VOLUME'})\n except Exception: pass\nb=pd.DataFrame(alerts); b.to_csv('breakout_alerts.csv',index=False); print('\\nEARLY-ENTRY RADAR (first 50)\\n',r.sort_values(['Volume_Dry','60D_Trend_%'],ascending=[False,False]).head(50).to_string(index=False) if len(r) else 'No radar matches today.'); print('\\nINTRADAY BREAKOUT ALERTS\\n',b.to_string(index=False) if len(b) else 'No qualifying 5-minute breakouts found among the top 35 radar stocks.'); print('\\nSaved early_entry_radar.csv and breakout_alerts.csv')")
